import { gsap } from 'gsap';
import { Group } from 'three/webgpu';
import { Object3D } from 'three/webgpu';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [meshUrl]
 * @property {any} [textContent]
 * @property {Array<{name:string,params:any,trigger?:string}>} [cinematicPrimitives]
 * @property {any} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{ loadTexture(url:string):Promise<any> }} textureLoader
 * @property {{ loadGLB(url:string):Promise<any> }} glbLoader
 * @property {{ loadVideo?(url:string):Promise<any> }} videoLoader
 * @property {{ createText(content:string, opts?:any): Object3D }} fontAtlas
 * @property {{ [key:string]:(target:any, params:any)=>{timeline:any, cleanup:()=>void} }} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

/**
 * Creates a thumbnail card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'ThumbnailCard';

  /** @type {Array<any>} */
  const activeTimelines = [];
  /** @type {any} */
  let loadedGLTF = null;
  /** Base Y position for hover animation */
  const baseY = 0;

  // Load GLB mesh (synchronous function, async side‑effect)
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      loadedGLTF = gltf;
      const scene = gltf.scene || gltf;
      root.add(scene);
    });
  }

  // Hover handler (expects a boolean: true = enter, false = leave)
  const hoverHandler = (enter) => {
    // kill any existing hover timeline
    activeTimelines
      .filter((t) => t._type === 'hover')
      .forEach((t) => t.kill());

    const tl = gsap.timeline({ _type: 'hover' });
    activeTimelines.push(tl);

    tl.to(
      root.position,
      {
        y: enter ? baseY + 0.15 : baseY,
        duration: 0.2,
        ease: 'power3.out',
      },
      0
    );
  };

  // Click handler (press‑down animation + emit)
  const clickHandler = () => {
    // kill any existing press timeline
    activeTimelines
      .filter((t) => t._type === 'press')
      .forEach((t) => t.kill());

    const tl = gsap.timeline({ _type: 'press' });
    activeTimelines.push(tl);

    tl.to(
      root.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      },
      0
    )
      .to(
        root.scale,
        {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.05,
          ease: 'power1.out',
        },
        '+=0.02'
      )
      .call(() => {
        ctx.emit('hub-home.select');
      });
  };

  // Expose handlers via userData
  root.userData.handlers = {
    hover: hoverHandler,
    click: clickHandler,
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill all GSAP timelines
    activeTimelines.forEach((t) => t.kill());
    activeTimelines.length = 0;

    // Dispose GLTF resources if loaded
    if (loadedGLTF) {
      const disposeNode = (obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m && m.dispose && m.dispose());
          } else {
            obj.material.dispose();
          }
        }
        if (obj.texture) {
          obj.texture.dispose();
        }
        if (obj.children) obj.children.forEach(disposeNode);
      };
      disposeNode(loadedGLTF.scene || loadedGLTF);
    }

    // Remove all children from root
    root.traverse((child) => {
      if (child !== root) {
        root.remove(child);
      }
    });
  };

  return root;
}
